            `})]})},DT=()=>{const[i,l]=k.useState(0);return k.useEffect(()=>{const d=setInterval(()=>{l(y=>{const g=y+1;return g>=100?(clearInterval(d),100):g})},25);return()=>clearInterval(d)},[]),S.jsxs("div",{className:"loading-screen",children:[S.jsxs("div",{className:"loader-container",children:[S.jsxs("svg",{className:"progress-ring",width:"200",height:"200",viewBox:"0 0 200 200",children:[S.jsx("circle",{className:"progress-ring__background",stroke:"rgba(255, 255, 255, 0.1)",strokeWidth:"12",fill:"transparent",r:"80",cx:"100",cy:"100"}),S.jsx("circle",{className:"progress-ring__circle",stroke:"#38bdf8",strokeWidth:"12",strokeLinecap:"round",fill:"transparent",r:"80",cx:"100",cy:"100",style:{strokeDasharray:"502.65",strokeDashoffset:502.65-502.65*i/100,transition:"stroke-dashoffset 0.05s linear"}})]}),S.jsxs("div",{className:"percentage-container",children:[S.jsx("span",{className:"percentage",children:Math.round(i)}),S.jsx("span",{className:"symbol",children:"%"})]})]}),S.jsx("style",{children:`
